arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup and register the pooled prediction engine
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");

// Load raw CSV and add a boolean Label column
var rawData = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
var labeledData = mlContext.Transforms.CustomMapping<CustomerData, ChurnLabel>(
    (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
    contractName: null).Fit(rawData).Transform(rawData);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.Age)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.Income)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age), nameof(CustomerData.Income),
        nameof(CustomerData.PurchaseHistory), "RegionEncoded"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

// Use train/test split when dataset is large enough, otherwise train on all data
var rowCount = (int)labeledData.GetColumn<float>("Age").LongCount();
ITransformer model;
if (rowCount >= 20)
{
    var split = mlContext.Data.TrainTestSplit(labeledData, testFraction: 0.2);
    model = pipeline.Fit(split.TrainSet);

    var testPredictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(testPredictions, labelColumnName: "Label");
    Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
else
{
    Console.WriteLine($"Dataset has only {rowCount} rows — training on all data (add ≥20 rows for train/test evaluation).");
    model = pipeline.Fit(labeledData);
}

// Save model and register pooled prediction engine
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");
mlContext.Model.Save(model, labeledData.Schema, modelPath);

builder.Services.AddPredictionEnginePool<ModelInput, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with customer data");

app.MapPost("/predict", (PredictionEnginePool<ModelInput, ChurnPrediction> pool, ModelInput input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel ? "Yes" : "No",
        Probability = prediction.Probability,
        Score = prediction.Score
    });
});

app.Run();

// Used for loading CSV data (includes label column)
